const fs = require('fs')
const os = require('os')
const path = require('path')
const run_command = require('run-command')

module.exports = shell_extensions

// user installed extensions as synced keys: /extensions/<uuid> -> "'enabled'" or "'disabled'"
// missing ones are installed from extensions.gnome.org, nothing is ever uninstalled
function shell_extensions ({ dconf, env = process.env, ego_url = 'https://extensions.gnome.org', shell_version = null }) {
  const data_dir = env.XDG_DATA_HOME || path.join(os.homedir(), '.local', 'share')
  const extensions_dir = path.join(data_dir, 'gnome-shell', 'extensions')
  const api = { read_all, write, owns: key => key.startsWith('/extensions/') }
  return api

  async function read_all () {
    const enabled = parse_list(await dconf.read('/org/gnome/shell/enabled-extensions'))
    const all = {}
    for (const uuid of await list_installed(extensions_dir)) all['/extensions/' + uuid] = enabled.includes(uuid) ? "'enabled'" : "'disabled'"
    return all
  }

  // null (removed on the other device) only disables it here
  async function write (key, value) {
    const uuid = key.slice('/extensions/'.length)
    if (!/^[\w-][\w.@-]*$/.test(uuid)) throw new Error('not a valid extension uuid: ' + uuid) // it becomes a folder name
    if (value !== null && !(await read_metadata(extensions_dir, uuid))) await install(uuid)
    await set_enabled(uuid, value === "'enabled'")
  }

  async function install (uuid) {
    const major = shell_version || await read_shell_version()
    const info = await fetch(`${ego_url}/extension-info/?uuid=${encodeURIComponent(uuid)}&shell_version=${major}`)
    if (!info.ok) throw new Error(`${uuid} is not on extensions.gnome.org`)
    const zip = path.join(os.tmpdir(), `gnome-hypersync-${process.pid}-${uuid}.zip`)
    await fs.promises.writeFile(zip, Buffer.from(await (await fetch(ego_url + (await info.json()).download_url)).arrayBuffer()))
    await run_command({ command: 'gnome-extensions', args: ['install', '--force', zip], env }).finally(() => fs.promises.rm(zip, { force: true }))
    const metadata = await read_metadata(extensions_dir, uuid)
    if (metadata?.['shell-version']?.includes(String(major))) return
    await fs.promises.rm(path.join(extensions_dir, uuid), { recursive: true, force: true }) // extensions.gnome.org gives the newest version even if it does not fit
    throw new Error(`${uuid} does not support GNOME ${major}`)
  }

  async function set_enabled (uuid, on) {
    const enabled = parse_list(await dconf.read('/org/gnome/shell/enabled-extensions')).filter(id => id !== uuid)
    if (on) enabled.push(uuid)
    await dconf.write('/org/gnome/shell/enabled-extensions', format_list(enabled))
  }
}

/***************************************
HELPERS
***************************************/
async function list_installed (extensions_dir) {
  const names = await fs.promises.readdir(extensions_dir).catch(() => [])
  const installed = []
  for (const name of names) if (await read_metadata(extensions_dir, name)) installed.push(name)
  return installed
}

function read_metadata (extensions_dir, uuid) {
  return fs.promises.readFile(path.join(extensions_dir, uuid, 'metadata.json'), 'utf8').then(JSON.parse).catch(() => null)
}

// "['a@b', 'c@d']" or "@as []" <-> ['a@b', 'c@d'], uuids never contain quotes
function parse_list (text) { return [...(text || '').matchAll(/'([^']*)'/g)].map(match => match[1]) }
function format_list (list) { return list.length ? `[${list.map(id => `'${id}'`).join(', ')}]` : '@as []' }

async function read_shell_version () { return (await run_command({ command: 'gnome-shell', args: ['--version'] })).match(/(\d+)/)[1] }
